def fit_a0(cal, coords, n):
    by = {}
    for mm in cal:
        for rx in mm.receptions:
            if rx.gid in coords:
                d = float(np.linalg.norm(coords[rx.gid] - np.array([mm.x, mm.y]))) + 1.0
                by.setdefault(rx.gid, []).append(rx.rssi + 10 * n * math.log10(d))
    return {g: float(np.median(v)) for g, v in by.items() if len(v) >= 10}

def wcl_estimate(gw_xy: np.ndarray, rssi: np.ndarray) -> np.ndarray:
    """
    Weighted centroid with RSSI-based weights.
    """
    # shift to positive weights: w ~ 10^(rssi/10)
    w = np.power(10.0, rssi / 10.0)
    s = float(np.sum(w))
    if s <= 0:
        return np.mean(gw_xy, axis=0)
    return np.array([float(np.sum(w * gw_xy[:, 0]) / s), float(np.sum(w * gw_xy[:, 1]) / s)], dtype=float)
